package edu.ankara.audiometer.ui.view;
import edu.ankara.audiometer.domain.model.*;import javafx.collections.*;import javafx.scene.control.*;
public final class ResultPanel extends TitledPane { private final TableView<AudiogramPoint> table=new TableView<>(); public ResultPanel(){ setText("Results / Completed Thresholds"); setCollapsible(false); table.setPrefHeight(250); TableColumn<AudiogramPoint,String> ear=new TableColumn<>("Ear"); ear.setCellValueFactory(c->new javafx.beans.property.SimpleStringProperty(c.getValue().ear().name())); TableColumn<AudiogramPoint,Number> f=new TableColumn<>("Hz"); f.setCellValueFactory(c->new javafx.beans.property.SimpleIntegerProperty(c.getValue().frequency().value())); TableColumn<AudiogramPoint,Number> db=new TableColumn<>("dB HL"); db.setCellValueFactory(c->new javafx.beans.property.SimpleIntegerProperty(c.getValue().thresholdDbHL().value())); TableColumn<AudiogramPoint,String> notes=new TableColumn<>("Notes"); notes.setCellValueFactory(c->new javafx.beans.property.SimpleStringProperty(c.getValue().notes())); table.getColumns().addAll(ear,f,db,notes); setContent(table);} public void update(Audiogram a){ table.setItems(FXCollections.observableArrayList(a.points())); } }
